#!ibl edition=2
$root = "/Users/kangkukjin/Desktop/AI/indiebizOS/outputs/long_sentence_imagination/2026-10-18_76회차"
$out = f"${$root}/ai/variant"
$rows = $입력
$g = $rows >> [table:groupby]{by:"state",agg:{count:["count"]}}
$cm = from_entries($g >> [table:each]{ return [$it.state,$it.count] })
$counts = {unchanged:get($cm,"unchanged",0),changed:get($cm,"changed",0),missing:get($cm,"missing",0),unknown:get($cm,"unknown",0),total:len($rows)}
assert $counts.unchanged + $counts.changed + $counts.missing + $counts.unknown == len($rows), "합계 불일치", $counts
$limits = [
  "이번 검토는 기존 근거의 판본 변화만 대조했다. claim(사용자 선언)의 진실성·의미 정확성은 검증하지 않았다.",
  "excerpt·claim·note_id는 직전 결과(ai/base/report.json)의 최초 값을 그대로 보존했고 note를 다시 만들지 않았다. current_read는 참고용 현재 읽기이며 상태 판정의 근거가 아니다.",
  "현재성은 각 근거의 선언 범위(1~3줄, sha256_utf8_lines)만 대조했다. scope.complete=false — D2처럼 범위 밖에 생긴 변화는 이 판정에 나타나지 않는다.",
  "D3 missing은 기존 경로에서 파일을 찾지 못했다는 뜻이다(not_found). 다른 위치로 옮겨졌는지는 추적하지 않았다.",
  "D1 changed는 지정 범위의 판본이 바뀌었다는 뜻이며, 단언이 거짓이 되었다는 판정이 아니다. 단언은 폐기하지 않았다.",
  "receipt_availability=not_checked — 원 관측 영수증 원본이 지금도 보관돼 있는지는 따로 검사하지 않았다.",
  "검사 시각(checked_at) 이후 자료가 바뀌면 상태는 달라질 수 있다."
]
$report = {title:"76회차 시스템 인수 검토표 — 변형(판본 변화 재대조)",manifest:f"${$root}/inputs/ai/manifest.json",previous_report:f"${$root}/ai/base/report.json",rows:$rows,counts:$counts,limits:$limits}
$w1 = [self:write]{path:f"${$out}/report.json",content:json($report)}
[def:행md]($r) {
  $ex = strip($r.excerpt)
  $o = $r.evidence_status == null ? {} : $r.evidence_status.outcomes[0]
  $c = $r.current_read
  $curline = $c.read == "ok" ? f"읽음, 최초 발췌와 같음=${json($c.same_as_original)}, 관측 영수증 `${$c.observation_ref}`" : f"읽기 실패 ${get($c,'code')}: ${get($c,'reason')}"
  return f"""## ${$r.id}
- 출처: `${$r.path}` ${$r.source.start_line}~${$r.source.end_line}줄 (최초 읽기 때 전체 ${$r.source.total_lines}줄, numbered=${json($r.source.numbered)})
- 최초 읽기 관측 영수증: `${$r.source.observation_ref}`
- claim (사용자 선언 — 정확성 미검증): ${$r.claim}
- note_id: ${$r.note_id} (기존 note 재사용, 찾음=${json($r.note_found)}, locus=입력 파일 일치: ${json($r.note_locus_matches_path)})
- 현재성: **${$r.state}** (직전 ${$r.previous_state}) — comparison=${get($r.evidence_status,"comparison")}, checked=${get($r.evidence_status,"checked")}, unchecked=${get($r.evidence_status,"unchecked")}, method=${get($o,"method")}, reason=${get($o,"reason")}, 영수증=${json(get($o,"observation_ref"))}, 범위=${json(get($o,"scope"))}, checked_at=${get($r.evidence_status,"checked_at")}
- 참고 현재 읽기(판정 근거 아님): ${$curline}

최초 발췌:
```text
${$ex}
```
"""
}
$body = $rows >> [table:each]{ [fn:행md]{r:$it} }
$table = $rows >> [table:each]{ return f"| ${$it.id} | `${split($it.path,'/')[-1]}` | ${$it.source.start_line}~${$it.source.end_line} | ${json($it.source.numbered)} | ${$it.note_id} | ${$it.previous_state} | ${$it.state} |" }
$md = f"""# 76회차 시스템 인수 검토표 — 변형(판본 변화 재대조)

명부: `${$report.manifest}`
직전 결과: `${$report.previous_report}`

> 이번 검토는 판본 변화만 확인한다. claim은 원천에 대한 사용자 선언이며, 이 검토는 그 정확성을 검증하지 않았다.

| id | 파일 | 줄 | numbered | note_id | 직전 | 현재성 |
|---|---|---|---|---|---|---|
${join("\n",$table)}

## 합계
unchanged ${$counts.unchanged} · changed ${$counts.changed} · missing ${$counts.missing} · unknown ${$counts.unknown} · 합 ${$counts.total}

${join("\n",$body)}
## 미확인 한계
${join("\n",$limits >> [table:each]{ return f"- ${$it}" })}
"""
$w2 = [self:write]{path:f"${$out}/report.md",content:$md}
$base = [self:read]{path:f"${$root}/ai/base/report.json"}
$rj = [self:read]{path:f"${$out}/report.json"}
$rm = [self:read]{path:f"${$out}/report.md"}
$d = $rj.data
$ids = $d.rows >> [table:each]{ return $it.id }
$pairs = zip($d.rows,$base.data.rows)
$chk = {
  ids_order:$ids == ["D1","D2","D3","D4","D5","D6"],
  note_ids_preserved:all($pairs >> [table:each]{ return $it[0].note_id == $it[1].note_id }),
  excerpts_preserved:all($pairs >> [table:each]{ return $it[0].excerpt == $it[1].excerpt }),
  claims_preserved:all($pairs >> [table:each]{ return $it[0].claim == $it[1].claim }),
  states:$d.rows >> [table:each]{ return $it.state },
  counts_sum:$d.counts.unchanged + $d.counts.changed + $d.counts.missing + $d.counts.unknown == len($d.rows),
  counts_equal:$d.counts == $counts,
  md_has_all_ids:all($ids >> [table:each]{ return contains($rm.text,f"## ${$it}") }),
  md_has_disclaimer:contains($rm.text,"정확성을 검증하지 않았다"),
  md_has_limits:contains($rm.text,"## 미확인 한계"),
  md_has_sum:contains($rm.text,f"합 ${$counts.total}")
}
return {counts:$counts,checks:$chk,w1:$w1.path,w2:$w2.path}
